import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const worldFistCard='a2-p10-r1c1';
export const worldFistScenarios=['world-fist-ordinary','world-fist-owner-ordinary','world-fist-low','world-fist-dedicated','world-fist-far','world-fist-same-faction','world-fist-water','world-fist-equal','world-fist-lower','world-fist-maai-one-ordinary','world-fist-maai-one-dedicated','world-fist-evade-ordinary','world-fist-evade-dedicated','world-fist-fate','world-fist-suppressed','world-fist-silenced','world-fist-stopped','world-fist-wrong-owner','world-fist-decline','world-fist-noncounter','world-fist-black-ordinary','world-fist-black-dedicated','world-fist-dead-ordinary','world-fist-dead-dedicated','world-fist-black-maai','world-fist-dead-evade','world-fist-black-fate','world-fist-black-decline','world-fist-white-prohibited'] as const;
export type WorldFistScenario=typeof worldFistScenarios[number];
export function isWorldFistScenario(name:string):name is WorldFistScenario{return (worldFistScenarios as readonly string[]).includes(name);}
export function worldFistMode(name:WorldFistScenario){const suffix=name.replace('world-fist-',''),dedicated=!(suffix.includes('ordinary')||['low','decline','white-prohibited','black-decline'].includes(suffix)),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',black=suffix.startsWith('black-'),dead=suffix.startsWith('dead-'),follower=black?'a2-p22-r1c2':dead?'a2-p22-r3c2':suffix==='water'?'a2-p23-r1c1':suffix==='equal'?'a2-p22-r1c1':suffix==='lower'?'a2-p19-r1c3':null,maai=suffix.startsWith('maai')||suffix==='black-maai',evade=suffix.startsWith('evade')||suffix==='dead-evade',cancel=suffix.endsWith('fate'),decline=suffix.endsWith('decline');return {suffix,dedicated,owner,black,dead,follower,maai,evade,cancel,decline};}
export function makeWorldFistPhysical(name:WorldFistScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=worldFistMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.suffix==='white-prohibited'?'不死王ガドューラ':m.owner?'大神官ジル':'侍大将のシン','黒騎士ガーウィン','小人のランバ','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?11:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?6:m.dedicated?0:7))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,worldFistCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c1')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.black||m.dead)keep.push(takeCard(s,c,'a2-p19-r3c2'));if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.maai)keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.evade)keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`WORLD_FIST_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WORLD_FIST_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WORLD_FIST_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('WORLD_FIST_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if((m.black||m.dead)&&id===c)act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p19-r3c2'});if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('WORLD_FIST_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
